export function appUrl(id,params={}){const app=appRegistry(true).find(app=>app.id===id);if(!app)throw new Error('Unknown app');const url=new URL(app.url);if(id==='professy')url.pathname='/user-home';else if(id==='people')url.pathname='/people';for(const [key,value] of Object.entries(params))if(value!=null&&!(id==='calendar'&&key==='projectId'))url.searchParams.set(key,String(value));return url.toString();}
const base=()=>`${location.protocol}//${host()}:8086/auth`;
const random=()=>btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(32)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
export class SuiteAuth {
 constructor(clientId){this.clientId=clientId;this.csrf='';}
 async call(path,method='GET',body,token){const response=await fetch(base()+path,{method,credentials:'include',headers:{'X-GP-Client':this.clientId,...(this.csrf?{'X-CSRF-Token':this.csrf}:{}),...(body!==undefined?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body===undefined?undefined:JSON.stringify(body)});let data={};try{data=await response.json();}catch{}if(!response.ok){const error=new Error(data.message||data.detail||'Shared sign-in is unavailable.');error.status=response.status;throw error;}if(data.csrf)this.csrf=data.csrf;return data;}
 async adopt(token,replace=false){return this.call('/session','POST',{remember:true,replace},token);}
 async resume(){await this.call('/session');return this.call('/access','POST',{clientId:this.clientId});}
 async bootstrap(){const url=new URL(location.href),code=url.searchParams.get('sso_code'),state=url.searchParams.get('sso_state');if(code){const key=`gp.sso.${this.clientId}.${state}`,saved=JSON.parse(sessionStorage.getItem(key)||'null');if(!saved||Date.now()-saved.created>600000)throw new Error('Sign-in expired. Please sign in again.');const result=await this.call('/token','POST',{code,verifier:saved.verifier,clientId:this.clientId,redirectUri:saved.redirectUri});sessionStorage.removeItem(key);history.replaceState(null,'',saved.returnTo);return result.data;}try{return (await this.resume()).data;}catch(error){if(error.status===401)return null;throw error;}}
 async signIn(){const state=random(),verifier=random(),redirectUri=location.origin+'/';const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)));const challenge=btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');sessionStorage.setItem(`gp.sso.${this.clientId}.${state}`,JSON.stringify({verifier,redirectUri,returnTo:location.pathname+location.search+location.hash,created:Date.now()}));const url=new URL(appUrl('identity'));for(const [key,value] of Object.entries({clientId:this.clientId,redirectUri,state,challenge}))url.searchParams.set(key,value);location.assign(url);}
 async logout(){try{await this.call('/session');await this.call('/logout','POST',{});}catch(error){if(error.status!==401)throw error;}}
}
export function defineAppMenu(){defineBrand();if(typeof window==='undefined'||customElements.get('gp-apps'))return;customElements.define('gp-apps',class extends HTMLElement{
 connectedCallback(){if(this.shadowRoot)return;const shadow=this.attachShadow({mode:'open'});shadow.innerHTML=`<style>:host{display:inline-block;position:relative;font-family:'Google Sans',Inter,sans-serif}button{font:inherit;cursor:pointer}button.launch{height:50px;border:1px solid var(--gp-border-color, #a0a6b1);border-radius:10px;background:white;color:#40536e;padding:0 13px;font-size:14px;font-weight:600}.launch span{font-size:20px;margin-right:8px}.panel{position:absolute;top:58px;right:0;width:330px;max-width:calc(100vw - 24px);padding:18px;background:white;border:1px solid var(--gp-border-color, #a0a6b1);border-radius:10px;box-shadow:0 16px 50px #172b4d25;z-index:9999}.panel{max-height:calc(100dvh - 100px);overflow:auto;overscroll-behavior:contain}.panel[hidden]{display:none}.heading{display:flex;align-items:center;justify-content:space-between;color:#8795aa;font-size:10px;letter-spacing:1.5px;padding:3px 5px 15px}.heading button{border:0;background:none;color:#798ba5;font-size:20px}.app{display:flex;width:100%;text-align:left;gap:13px;align-items:center;border:0;border-radius:10px;background:white;padding:12px;color:#304562}.app:hover{background:#f2f6fd}.app i{position:relative;width:40px;height:40px;display:grid;place-items:center;border-radius:10px;color:white;font-style:normal;font-size:18px;font-weight:600}.app i:after{display:none;content:"";position:absolute;bottom:-3px;left:5px;right:5px;height:3px;border-radius:3px;background:linear-gradient(90deg,#4285f4 25%,#34a853 25%,#34a853 50%,#fbbc04 50%,#fbbc04 75%,#ea4335 75%)}:host-context([data-theme="dark"]) .panel,:host-context([data-theme="dark"]) .app,:host-context([data-theme="dark"]) button.launch{background:#181e29;color:#e6ecf5;border-color:var(--gp-border-color, #a0a6b1)}:host-context([data-theme="dark"]) .app:hover{background:#263348}.app strong{display:block;font-size:14px}.app small{display:block;margin-top:5px;font-size:11px;color:#8a98ac}.footer{font-size:10px;color:#9aa5b7;padding:16px 5px 3px;border-top:1px solid var(--gp-border-color, #a0a6b1);margin-top:10px}</style><style>${launcherVisualStyles}${cleanVisualStyles('launcher',this.getAttribute('current'),{sharedChrome:this.hasAttribute('shared-chrome')})}${borderlessVisualStyles('launcher')}${awsConsoleLauncherStyles}@layer gp-flat-chrome {:host([icon-only]) button.launch.launch{display:grid!important;place-items:center!important;width:40px!important;height:40px!important;min-height:40px!important;padding:0!important;border:0!important;border-radius:50%!important;background:transparent!important;color:var(--gp-text,#444746)!important;font-size:0!important;box-shadow:none!important}:host([icon-only]) button.launch.launch:hover{background:var(--gp-surface-muted,#f1f3f4)!important}:host([icon-only]) .launch span{display:block;width:18px;height:18px;margin:0!important;font-size:0!important;background:radial-gradient(circle,currentColor 2px,transparent 2.5px) 0 0/6px 6px}}</style><button type="button" class="launch" aria-label="Apps" aria-haspopup="dialog" aria-expanded="false"><span>▦</span>Apps</button><section class="panel" hidden role="dialog" aria-label="Greatley Poshley apps"><div class="heading">All apps · ${appRegistry().length}<button aria-label="Close apps">×</button></div><div class="apps-list">${appRegistry().map(app=>`<button class="app" data-app="${app.id}" ${app.id===this.getAttribute('current')?'aria-current="page"':''}><i><img src="${app.logo}" alt="" width="40" height="40"></i><span class="app-copy"><strong>${app.name}</strong><small>${app.caption}</small></span><span class="app-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div class="workspace-tools"><span>In Professy</span><button type="button" data-workspace="agents"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v3M9 3h6M5 7h14v13H5ZM2 11v5m20-5v5M8 11h1m6 0h1M9 16h6"></path></svg>Agents</button><button type="button" data-workspace="roadmap"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4v16M4 7h6l3 4h7M4 17h8"></path></svg>Roadmap</button></div><div class="footer">One account. Connected work.</div></section>`;const panel=shadow.querySelector('.panel'),launch=shadow.querySelector('.launch'),appsList=shadow.querySelector('.apps-list');this.resizeApps=()=>{const narrow=innerWidth<=520;panel.style.setProperty('width',innerWidth<=380?'calc(100vw - 20px)':narrow?'min(700px,calc(100vw - 24px))':'min(900px,calc(100vw - 32px))','important');panel.style.setProperty('max-width',innerWidth<=380?'calc(100vw - 20px)':'calc(100vw - 32px)','important');appsList.style.setProperty('grid-template-columns',innerWidth<=380?'1fr':narrow?'repeat(2,minmax(0,1fr))':'repeat(4,minmax(0,1fr))','important');appsList.style.setProperty('background','#fff','important');for(const item of appsList.querySelectorAll('.app')){item.style.setProperty('background','#fff','important');if(item.hasAttribute('aria-current'))item.style.setProperty('box-shadow','inset 3px 0 #0972d3','important');}};this.resizeApps();window.addEventListener('resize',this.resizeApps);launch.onclick=()=>{panel.hidden=!panel.hidden;launch.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)shadow.querySelector('.heading button').focus();};shadow.querySelector('.heading button').onclick=()=>{panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus();};for(const button of shadow.querySelectorAll('[data-app]'))button.onclick=()=>{const app=button.dataset.app;const event=new CustomEvent('gp-app-open',{detail:{app,projectId:Number(this.getAttribute('project-id'))||null},bubbles:true,composed:true,cancelable:true});if(this.dispatchEvent(event))window.open(appUrl(app,{projectId:this.getAttribute('project-id')}),'_blank','noopener');panel.hidden=true;launch.setAttribute('aria-expanded','false');};for(const button of shadow.querySelectorAll('[data-workspace]'))button.onclick=()=>{window.open(appUrl('professy',{menu:button.dataset.workspace,projectId:this.getAttribute('project-id')}),'_blank','noopener');panel.hidden=true;launch.setAttribute('aria-expanded','false');};shadow.addEventListener('keydown',event=>{if(panel.hidden)return;if(event.key==='Escape'){event.preventDefault();panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus();}if(event.key==='Tab'){const buttons=[...panel.querySelectorAll('button')];const first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&shadow.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&shadow.activeElement===last){event.preventDefault();first.focus();}}});this.outside=event=>{if(!event.composedPath().includes(this)){panel.hidden=true;launch.setAttribute('aria-expanded','false');}};document.addEventListener('click',this.outside);}
 disconnectedCallback(){if(this.outside)document.removeEventListener('click',this.outside);if(this.resizeApps)window.removeEventListener('resize',this.resizeApps);}
});}

